### Step 1: Install Allegro Library
First, you need to install the Allegro library. You can download it from the official website or use a package manager if you're on a Linux system.

For Ubuntu, you can install it using:
```bash
sudo apt-get install liballegro5-dev
```

### Step 2: Set Up Your Development Environment
Ensure your development environment is set up to compile C programs with Allegro. You'll need to link against the Allegro library when compiling.

### Step 3: Write the Code
Below is a basic example of how you might structure your Snake game in C using Allegro. This example includes loading images, handling input, and updating the game state.

```c
#include <allegro5/allegro.h>
#include <allegro5/allegro_image.h>
#include <allegro5/allegro_primitives.h>
#include <allegro5/allegro_native_dialog.h>

#define SCREEN_WIDTH 640
#define SCREEN_HEIGHT 480
#define SNAKE_SIZE 20
#define SNAKE_SPEED 5

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point *body;
    int length;
    int direction;
} Snake;

ALLEGRO_DISPLAY *display = NULL;
ALLEGRO_EVENT_QUEUE *event_queue = NULL;
ALLEGRO_TIMER *timer = NULL;
ALLEGRO_BITMAP *snake_image = NULL;
ALLEGRO_BITMAP *food_image = NULL;
Snake snake;

void init_game() {
    snake.body = malloc(sizeof(Point) * 10);
    snake.length = 1;
    snake.direction = 0; // 0: right, 1: down, 2: left, 3: up
    snake.body[0].x = SCREEN_WIDTH / 2;
    snake.body[0].y = SCREEN_HEIGHT / 2;
}

void draw_game() {
    al_clear_to_color(al_map_rgb(0, 0, 0));
    for (int i = 0; i < snake.length; i++) {
        al_draw_bitmap(snake_image, snake.body[i].x, snake.body[i].y, 0);
    }
    al_draw_bitmap(food_image, 100, 100, 0); // Example food position
    al_flip_display();
}

void update_game() {
    Point new_head = snake.body[0];
    switch (snake.direction) {
        case 0: new_head.x += SNAKE_SPEED; break;
        case 1: new_head.y += SNAKE_SPEED; break;
        case 2: new_head.x -= SNAKE_SPEED; break;
        case 3: new_head.y -= SNAKE_SPEED; break;
    }
    for (int i = snake.length - 1; i > 0; i--) {
        snake.body[i] = snake.body[i - 1];
    }
    snake.body[0] = new_head;
}

int main(int argc, char **argv) {
    if (!al_init()) {
        al_show_native_message_box(display, "Error", "Failed to initialize Allegro", NULL, NULL, ALLEGRO_MESSAGEBOX_ERROR);
        return -1;
    }

    display = al_create_display(SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!display) {
        al_show_native_message_box(display, "Error", "Failed to create display", NULL, NULL, ALLEGRO_MESSAGEBOX_ERROR);
        return -1;
    }

    al_init_image_addon();
    al_init_primitives_addon();
    al_install_keyboard();
    timer = al_create_timer(1.0 / 10.0);
    event_queue = al_create_event_queue();
    al_register_event_source(event_queue, al_get_keyboard_event_source());
    al_register_event_source(event_queue, al_get_timer_event_source(timer));
    al_start_timer(timer);

    snake_image = al_load_bitmap("snake.png");
    food_image = al_load_bitmap("food.png");

    init_game();

    while (1) {
        ALLEGRO_EVENT ev;
        al_wait_for_event(event_queue, &ev);

        if (ev.type == ALLEGRO_EVENT_TIMER) {
            update_game();
            draw_game();
        } else if (ev.type == ALLEGRO_EVENT_KEY_DOWN) {
            switch (ev.keyboard.keycode) {
                case ALLEGRO_KEY_UP: snake.direction = 3; break;
                case ALLEGRO_KEY_DOWN: snake.direction = 1; break;
                case ALLEGRO_KEY_LEFT: snake.direction = 2; break;
                case ALLEGRO_KEY_RIGHT: snake.direction = 0; break;
            }
        } else if (ev.type == ALLEGRO_EVENT_DISPLAY_CLOSE) {
            break;
        }
    }

    al_destroy_bitmap(snake_image);
    al_destroy_bitmap(food_image);
    al_destroy_timer(timer);
    al_destroy_event_queue(event_queue);
    al_destroy_display(display);

    return 0;
}
```

### Step 4: Compile and Run
Compile your program with the Allegro library linked. For example:
```bash
gcc -o snake_game snake_game.c -lallegro -lallegro_primitives -lallegro_image -lallegro_ttf
```

Run the compiled program:
```bash
./snake_game
```

### Step 5: Enhance the Game
You can enhance the game by adding features like:
- Collision detection with walls and the snake's body.
- Growing the snake when it eats food.
- Scoring system.
- Different levels or increasing difficulty.

This is a basic framework to get you started. You can expand upon it to create a more complex and engaging game.

